const results = document.getElementById("results");
const status = document.getElementById("status");
const watchlist = document.getElementById("watchlist");
const empty = document.getElementById("empty");
let state = { data: { watchlist: [] }, revisions: { watchlist: {} } };

function showWatchlist() {
  watchlist.replaceChildren();
  empty.hidden = state.data.watchlist.length > 0;
  for (const film of state.data.watchlist) {
    const item = document.createElement("li");
    item.dataset.hook = "kept";
    item.textContent = film.title + " (" + film.year + ")";
    watchlist.append(item);
  }
}
const load = () => tessera.call("data.read").then((read) => { state = read; showWatchlist(); });

function filmItem(film) {
  const item = document.createElement("li");
  item.dataset.hook = "result";
  const poster = document.createElement("img");
  poster.alt = "Poster of " + film.title;
  tessera.connectionImageUrl({ connection: "movies", path: film.poster }).then(
    (url) => { poster.src = url; },
    () => { poster.alt = "No poster for " + film.title; },
  );
  const about = document.createElement("div");
  const title = document.createElement("h3");
  const name = document.createElement("span");
  name.dataset.hook = "result-title";
  name.textContent = film.title;
  title.append(name, " (" + film.year + ")");
  const keep = document.createElement("button");
  keep.type = "button";
  keep.dataset.hook = "result-keep";
  keep.textContent = "Add " + film.title + " to my watchlist";
  keep.addEventListener("click", () => {
    if (state.data.watchlist.some((kept) => kept.title === film.title)) return;
    tessera
      .call("data.patch", { operations: [{ op: "add", collection: "watchlist", record: { title: film.title, year: film.year } }] })
      .then(load, (error) => { status.textContent = error.message; });
  });
  const trailer = document.createElement("button");
  trailer.type = "button";
  trailer.textContent = "Watch the trailer of " + film.title;
  trailer.addEventListener("click", () => {
    tessera.openPage({ connection: "videos", path: film.trailer }).catch((error) => { status.textContent = error.message; });
  });
  about.append(title, keep, " ", trailer);
  item.append(poster, about);
  return item;
}

async function search(query) {
  status.textContent = "Searching…";
  try {
    const answer = await tessera.call("connection.request", {
      connection: "movies",
      method: "GET",
      path: "/search?genre=science-fiction&before=1970&query=" + encodeURIComponent(query),
    });
    if (answer.statusCode !== 200) {
      status.textContent = "The film service answered " + answer.statusCode + ". Try again later.";
      return;
    }
    const films = JSON.parse(answer.body).results;
    results.replaceChildren(...films.map(filmItem));
    status.textContent = films.length + " films, from your " + answer.source.connection + " connection.";
  } catch (error) {
    status.textContent = "The search didn't work: " + error.message;
  }
}

document.getElementById("search").addEventListener("submit", (event) => {
  event.preventDefault();
  search(document.getElementById("query").value);
});
load();
search(document.getElementById("query").value);

